                                    cellInternal.word = text;
                                    cellInternal.worInverted = textInverted;
                                    cellInternal.wordEn = textEn;
                                    cellInternal.wordEnInverted = textEnInverted;




                                    cell++;
                                    newRow.cells.Add(cellInternal);
